import{_ as a,o as e,c as n,ae as l}from"./chunks/framework.DJK_dC0-.js";const u=JSON.parse('{"title":"能力路径：从 Python 到 Agent 岗位","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/learning-path.md","filePath":"tutorial/learning-path.md"}'),s={name:"tutorial/learning-path.md"};function r(i,t,d,o,p,h){return e(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="能力路径-从-python-到-agent-岗位" tabindex="-1">能力路径：从 Python 到 Agent 岗位 <a class="header-anchor" href="#能力路径-从-python-到-agent-岗位" aria-label="Permalink to &quot;能力路径：从 Python 到 Agent 岗位&quot;">​</a></h1><p>本页解释课程如何按岗位终局组织，不把学习者锁在固定章节顺序中。完整能力、来源、角色和案例以仓库根目录 curriculum.json 为准。</p><h2 id="三条路线" tabindex="-1">三条路线 <a class="header-anchor" href="#三条路线" aria-label="Permalink to &quot;三条路线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路线</th><th>适合目标</th><th>主要产物</th></tr></thead><tbody><tr><td>Python Agent 应用</td><td>使用 LLM、工具、知识库和 API 交付业务 Agent</td><td>知识库 Agent、工具协议、评测报告</td></tr><tr><td>Python 后端</td><td>交付 API、异步任务、数据契约、持久化和部署</td><td>可测试的后端服务、Docker/CI</td></tr><tr><td>LLM 原理桥接</td><td>理解并手写自动微分、Attention、Transformer</td><td>clean-room 实现，转入 learn-llm</td></tr></tbody></table><p>三条路线共享 Python 核心、工程底座和数据契约。通过诊断后，已掌握节点从当前路线中裁剪，脆弱节点进入短修复任务。</p><h2 id="主线顺序" tabindex="-1">主线顺序 <a class="header-anchor" href="#主线顺序" aria-label="Permalink to &quot;主线顺序&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Python 核心</span></span>
<span class="line"><span>  → 工程环境与测试</span></span>
<span class="line"><span>  → 数据契约与运行时校验</span></span>
<span class="line"><span>  → 异步 / HTTP / SSE</span></span>
<span class="line"><span>  → FastAPI 后端</span></span>
<span class="line"><span>  → LLM API 与结构化输出</span></span>
<span class="line"><span>  → Tool Calling 与 Agent Loop</span></span>
<span class="line"><span>  → 知识库摄取、检索、引用和拒答</span></span>
<span class="line"><span>  → 权限、状态、恢复与 HITL</span></span>
<span class="line"><span>  → 评测、可观测性、成本和回归</span></span>
<span class="line"><span>  → Docker、CI、作品和面试表达</span></span></code></pre></div><h2 id="前端经验迁移" tabindex="-1">前端经验迁移 <a class="header-anchor" href="#前端经验迁移" aria-label="Permalink to &quot;前端经验迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>已有心智模型</th><th>Python Agent 中的对应物</th><th>迁移时必须补的内容</th></tr></thead><tbody><tr><td>TypeScript 类型</td><td>类型标注、dataclass、Pydantic</td><td>类型标注本身不做运行时校验</td></tr><tr><td>Promise / async</td><td>coroutine、TaskGroup、取消和超时</td><td>阻塞调用、异常聚合、资源释放</td></tr><tr><td>Express 中间件</td><td>FastAPI dependency</td><td>生命周期、输入输出契约和测试</td></tr><tr><td>Jest / Vitest</td><td>pytest fixtures、参数化和退出码</td><td>测试夹具、隔离和回归门禁</td></tr><tr><td>状态管理</td><td>Agent checkpoint 和恢复</td><td>外部副作用、幂等键和未知结果</td></tr><tr><td>API 调用</td><td>Tool schema 与 MCP</td><td>模型只提议，执行层负责安全</td></tr></tbody></table><h2 id="每个节点的最小交付" tabindex="-1">每个节点的最小交付 <a class="header-anchor" href="#每个节点的最小交付" aria-label="Permalink to &quot;每个节点的最小交付&quot;">​</a></h2><ul><li>一次冷启动预测或检索；</li><li>一个最小可运行实现；</li><li>一个故障注入和调试任务；</li><li>一个条件变化后的迁移任务；</li><li>一份能说明机制、边界和取舍的短解释；</li><li>一次延迟复测。</li></ul><p>完成课程页面不代表节点 mastered。状态由 learner events 中的 Explain、Perform、Debug、Transfer 和 Retain 证据共同决定。</p><h2 id="建议的第一条纵向切片" tabindex="-1">建议的第一条纵向切片 <a class="header-anchor" href="#建议的第一条纵向切片" aria-label="Permalink to &quot;建议的第一条纵向切片&quot;">​</a></h2><p>先完成 examples/knowledge_base_agent：</p><ol><li>用标准库读取合成知识库；</li><li>实现确定性检索；</li><li>返回带引用的回答或拒答；</li><li>加入只读工具和权限校验；</li><li>跑 golden set 指标；</li><li>注入一次工具错配和一次回归；</li><li>写出故障复盘和迁移方案。</li></ol><p>完成这个切片后，再替换检索器、LLM 适配器、FastAPI 接口和持久化层。这样每次增加框架都能保持同一份业务验收合同。</p><h2 id="llm-原理桥接" tabindex="-1">LLM 原理桥接 <a class="header-anchor" href="#llm-原理桥接" aria-label="Permalink to &quot;LLM 原理桥接&quot;">​</a></h2><p><code>llm-clean-room-bridge</code> 从本仓库的 Python 工程能力出发，按以下顺序准备迁移证据：</p><ol><li>用 NumPy 表达批次、序列和特征维度，给矩阵乘法与广播写 shape 断言，并修复一个维度错误；</li><li>手写最小标量自动微分，对加法、乘法和组合运算做有限差分对拍，保留失败与修复记录；</li><li>实现最小 Attention 的打分、mask、归一化和输出，验证 shape 与被遮挡位置不会影响结果。</li></ol><p>每个练习需要源码、可重复测试和无提示解释，不能以调用现成模型代替实现证据。完成后进入 <a href="https://github.com/zenHeart/learn-llm" target="_blank" rel="noreferrer">learn-llm 原理课程</a>，一周后从空接口重建关键函数。本页是迁移入口与验收合同，尚不提供这些练习的完成回执。</p>`,20)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
